// 140+ more hand-made React components at https://studios.lou15.com/?ref=21st-code

import * as React from "react"

/** Fills its parent (give the parent a size); the grid is fitted inside at any aspect. */
export interface TubeGridProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Content layered over the tubes, centred. */
  children?: React.ReactNode
  /** Number of tube rows. 5 is the reference look. */
  rows?: number
  /** Number of tube columns. 5 is the reference look. */
  cols?: number
  /** Main electric blue of the tubes (the mid tone of the light ramp). Any CSS colour. */
  color?: string
  /** Brightest light inside the discs and along the lit walls. Any CSS colour. */
  highlight?: string
  /** Deep cobalt used for the shadowed side of each disc and the inner depths. Any CSS colour. */
  shade?: string
  /** Soft lavender cast mixed into some of the brighter light. Any CSS colour. */
  tint?: string
  /** Backdrop behind the grid. Any CSS colour. */
  background?: string
  /** Playback speed. 1 = one full camera orbit every 10 s. 0 holds the still frame. */
  speed?: number
  /** Strength of the soft breathing glow. 1 matches the design; 0 turns it off. */
  glow?: number
  /** The pointer steers the vanishing point and a click sends a pulse of light down the tubes. Off with reduced motion. */
  interactive?: boolean
  /** Accessible name. Without children the backdrop is announced as an image with this label. */
  label?: string
}

