// How far the vanishing point travels on its loop, in reference px, and how much the pointer steers it.
const ORBIT = [64, 40]
const STEER = 0.45

const VERT = `
attribute vec2 aPos;
uniform vec4 uBox;
uniform vec4 uView;
varying vec2 vP;
void main() {
  vP = mix(uBox.xy, uBox.zw, aPos);
  gl_Position = vec4((vP.x - uView.x) * uView.z, -(vP.y - uView.y) * uView.w, 0.0, 1.0);
}`

// The scene is drawn in light, not colour: each layer writes its light level (r) and lavender
// cast (g), blended over the layers behind, and a final pass maps light through the colour ramp.
// Soft edges and haze so fade through deep cobalt into the dark, as glowing light does.
const LIGHT = `
precision highp float;
uniform float uDither;
vec4 light(float q, float h, float a) {
  float n = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) - 0.5;
  return vec4(clamp(q + n * uDither, 0.0, 1.0), clamp(h + n * uDither, 0.0, 1.0), 0.0, a);
}`

// One tube body: an uneven capsule from the disc (radius R) to its far end near the vanishing
// point (radius R * s0), soft at the edges, lit along a stripe across its width.
const BODY_FRAG = `${LIGHT}
varying vec2 vP;
uniform vec2 uP;
uniform vec2 uF;
uniform vec4 uGeo;
uniform vec2 uTail;
uniform vec4 uB;
uniform vec3 uB2;
uniform vec4 uE;
uniform vec2 uPulse;
void main() {
  float R = uGeo.x, s0 = uGeo.y, blur = uGeo.z;
  vec2 D = uF - uP;
  float L2 = dot(D, D) + 1e-4;
  vec2 d = vP - uP;
  float t = dot(d, D) / L2;
  float tc = clamp(t, 0.0, 1.0);
  float rr = R * (1.0 + (s0 - 1.0) * tc);
  vec2 a = d - tc * D;
  float dist = length(a);
  float w = (D.x * a.y - D.y * a.x) / sqrt(L2) / rr;
  // deeper is softer, like a lens focused on the open ends
  float bw = (blur + uGeo.w * tc) / rr;
  float k = clamp((1.0 + bw - dist / rr) / (2.0 * bw), 0.0, 1.0);
  k = k * k * (3.0 - 2.0 * k);
  // a faint haze of scattered light around each body
  k = max(k, uTail.x * exp(-max(dist / rr - 1.0, 0.0) / uTail.y));
  float u = clamp(1.0 - t, 0.0, 1.0);
  float alpha = k * uE.z * clamp(u / 0.25, 0.0, 1.0);
  // the body starts at the disc: nothing of it shows behind the open end
  float nc = clamp((t * sqrt(L2) + 0.15 * R) / (0.4 * R), 0.0, 1.0);
  alpha *= nc * nc * (3.0 - 2.0 * nc);
  float sw = (w - uB.z) / max(uB.w, 0.05);
  float stripe = exp(-sw * sw);
  float sw2 = (w - uB2.y) / max(uB2.z, 0.05);
  float q = (uB.x + uB.y * stripe + uB2.x * exp(-sw2 * sw2)) * pow(max(u, 1e-4), uE.x);
  // the pulse: a band of light running from the far end out to the disc
  float bd = (t - uPulse.x) / 0.16;
  float band = exp(-bd * bd) * uPulse.y;
  q += band * (0.45 + 0.4 * stripe);
  alpha = max(alpha, k * band * nc * clamp(u / 0.1, 0.0, 1.0));
  if (alpha <= 0.002) discard;
  gl_FragColor = light(q, uE.y, alpha);
}`

// One disc: the open end, its light a fitted quartic field in the disc's own (turning) frame.
const DISC_FRAG = `${LIGHT}
varying vec2 vP;
uniform vec2 uP;
uniform vec4 uRot;
uniform vec4 uQ[5];
uniform vec3 uHq[2];
uniform vec3 uFx;
void main() {
  vec2 d = (vP - uP) / uRot.z;
  float r = length(d);
  float alpha = clamp((1.0 - r) * uRot.z / uFx.x + 0.5, 0.0, 1.0);
  if (alpha <= 0.0) discard;
  float x = uRot.x * d.x - uRot.y * d.y;
  float y = uRot.y * d.x + uRot.x * d.y;
  float x2 = x * x, y2 = y * y, xy = x * y;
  float r8 = (x2 + y2) * (x2 + y2);
  r8 *= r8;
  float q = dot(uQ[0], vec4(1.0, x, y, x2)) + dot(uQ[1], vec4(xy, y2, x2 * x, x2 * y))
    + dot(uQ[2], vec4(x * y2, y2 * y, x2 * x2, x2 * xy)) + dot(uQ[3], vec4(x2 * y2, xy * y2, y2 * y2, r8))
    + dot(uQ[4].xy, vec2(r8 * x, r8 * y));
  float h = dot(uHq[0], vec3(1.0, x, y)) + dot(uHq[1], vec3(x2, xy, y2));
  q = q * uFx.y + uFx.z;
  gl_FragColor = light(q, h, alpha);
}`

// The breathing glow: soft light added around each disc.
const GLOW_FRAG = `
precision highp float;
varying vec2 vP;
uniform vec2 uP;
uniform vec3 uG;
void main() {
  float r = length(vP - uP) / uG.x;
  float e = max(r - 0.9, 0.0) / 0.38;
  float g = exp(-e * e) * smoothstep(0.6, 1.0, r);
  gl_FragColor = vec4(g * uG.y, 0.0, 0.0, 0.0);
}`

const SCREEN_VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos * 2.0 - 1.0, 0.0, 1.0);
}`

// The light ramp: background, deep cobalt, cobalt, electric blue, periwinkle, highlight.
// The lavender cast warms the upper stops toward the tint.
const RAMP_FRAG = `
precision highp float;
varying vec2 vUv;
uniform sampler2D uLight;
uniform vec3 uBg;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
uniform vec3 uC4;
uniform vec3 uC5;
uniform vec3 uWarm;
void main() {
  vec4 L = texture2D(uLight, vUv);
  float s = clamp(L.r, 0.0, 1.0) * 5.0;
  vec3 c = mix(uBg, uC1, clamp(s, 0.0, 1.0));
  c = mix(c, uC2, clamp(s - 1.0, 0.0, 1.0));
  c = mix(c, uC3, clamp(s - 2.0, 0.0, 1.0));
  c = mix(c, uC4, clamp(s - 3.0, 0.0, 1.0));
  c = mix(c, uC5, clamp(s - 4.0, 0.0, 1.0));
  float w = 0.25 * clamp(s - 2.0, 0.0, 1.0) + 0.75 * clamp(s - 3.0, 0.0, 1.0) - 0.5 * clamp(s - 4.0, 0.0, 1.0);
  gl_FragColor = vec4(c + clamp(L.g, 0.0, 1.0) * w * uWarm, 1.0);
}`

function compile(gl: WebGLRenderingContext, type: number, src: string) {
  const s = gl.createShader(type)!
  gl.shaderSource(s, src)
  gl.compileShader(s)
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) console.error(gl.getShaderInfoLog(s))
  return s
}

type RGB = [number, number, number]

// Resolve any CSS colour (hex, rgb, oklch, color-mix...) to RGB in 0..1.
function readColor(css: string, ctx: CanvasRenderingContext2D | null): RGB {
  const hex = css.trim().match(/^#([\da-f]{3}|[\da-f]{6})$/i)
  if (hex) {
    const h = hex[1].length === 3 ? hex[1].replace(/./g, "$&$&") : hex[1]
    return [parseInt(h.slice(0, 2), 16) / 255, parseInt(h.slice(2, 4), 16) / 255, parseInt(h.slice(4, 6), 16) / 255]
  }
  if (!ctx) return [0, 0, 0]
  ctx.clearRect(0, 0, 1, 1)
  ctx.fillStyle = "#000" // ls:keep
  ctx.fillStyle = css
  ctx.fillRect(0, 0, 1, 1)
  const p = ctx.getImageData(0, 0, 1, 1).data
  return [p[0] / 255, p[1] / 255, p[2] / 255]
}

const mixc = (a: RGB, b: RGB, k: number): RGB => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]

// The six ramp stops and the lavender offset, from the colour props.
function palette(color: string, highlight: string, shade: string, tint: string, background: string) {
  const probe = typeof document !== "undefined" ? document.createElement("canvas") : null
  if (probe) probe.width = probe.height = 1
  const ctx = probe ? probe.getContext("2d", { willReadFrequently: true }) : null
  const bg = readColor(background, ctx)
  const c2 = readColor(shade, ctx)
  const c3 = readColor(color, ctx)
  const c5 = readColor(highlight, ctx)
  const lav = readColor(tint, ctx)
  const c1 = mixc(bg, c2, 0.52)
  const c4 = mixc(c3, c5, 0.37)
  const warm: RGB = [lav[0] - c4[0], lav[1] - c4[1], lav[2] - c4[2]]
  return { stops: [bg, c1, c2, c3, c4, c5] as RGB[], warm }
}

// Critically damped spring, integrated implicitly so any frame time is stable.
type Spring = { x: number; v: number }
function step(s: Spring, target: number, dt: number, omega: number) {
  const k = 1 + 2 * dt * omega
  const oo = omega * omega
  const det = 1 / (k + dt * dt * oo)
  const x = (k * s.x + dt * s.v + dt * dt * oo * target) * det
  s.v = (s.v + dt * oo * (target - s.x)) * det
  s.x = x
}

// The fitted profile that tube (i, j) borrows: the 5 x 5 reference, centred on the middle tube.
function profile(i: number, j: number, rows: number, cols: number) {
  const pi = ((((i - Math.floor((rows - 1) / 2) + 2) % 5) + 5) % 5)
  const pj = ((((j - Math.floor((cols - 1) / 2) + 2) % 5) + 5) % 5)
  return pi * 5 + pj
}

type Tube = { x: number; y: number; prof: number; ring: number; phase: number }

function layout(rows: number, cols: number): Tube[] {
  const out: Tube[] = []
  for (let i = 0; i < rows; i++)
    for (let j = 0; j < cols; j++) {
      const x = (j - (cols - 1) / 2) * PITCH
      const y = (i - (rows - 1) / 2) * PITCH
      out.push({ x, y, prof: profile(i, j, rows, cols), ring: Math.hypot(x, y) / PITCH, phase: ((i * 7 + j * 13) % 11) / 11 * TAU })
    }
  return out
}

// Scene state at loop phase ph (radians) with the pointer steer (sx, sy) in reference px.
// At ph = 0 with no steer it is exactly the fitted reference.
function scene(ph: number, sx: number, sy: number) {
  const vx = GLOBAL[0] + ORBIT[0] * Math.sin(ph) + sx
  const vy = GLOBAL[1] + ORBIT[1] * Math.sin(2 * ph) + sy
  const breath = 0.5 - 0.5 * Math.cos(2 * ph)
  return { vx, vy, breath, dvx: vx - GLOBAL[0], dvy: vy - GLOBAL[1] }
}

// How far each disc's light turns, radians: it follows the tube's angle to the vanishing point
// plus a slow sway of its own.
function lightTurn(t: Tube, vx: number, vy: number, ph: number) {
  const a0 = Math.atan2(t.y - GLOBAL[1], t.x - GLOBAL[0])
  const a1 = Math.atan2(t.y - vy, t.x - vx)
  let da = a1 - a0
  da = Math.atan2(Math.sin(da), Math.cos(da))
  const d = Math.hypot(t.x - vx, t.y - vy)
  const wgt = d / (d + PITCH * 0.6)
  return 1.1 * da * wgt + 0.35 * (Math.sin(ph + t.phase) - Math.sin(t.phase))
}

// The click pulse: where the band is along tube t (0 = disc, 1 = far end) and its strength,
// and how brightly the disc flashes when it arrives. tau in seconds since the click.
function pulseAt(t: Tube, tau: number) {
  if (tau < 0 || tau > 3) return { pos: 2, amp: 0, flash: 0 }
  const local = tau - t.ring * 0.16
  const pos = 1.15 - local * 1.9
  const amp = local > 0 ? Math.exp(-local * 0.9) : 0
  const arrive = (1.15 / 1.9)
  const flash = Math.exp(-Math.pow((local - arrive) / 0.18, 2)) * 0.9
  return { pos, amp, flash }
}

/** A grid of glowing electric-blue tubes seen end-on, extruded toward a drifting vanishing point. */
export function TubeGrid({
  children,
  rows = 5,
  cols = 5,
  color = "#3644f2",
  highlight = "#e0eafd",
  shade = "#0511b7",
  tint = "#8c80fc",
  background = "#000000",
  speed = 1,
  glow = 1,
  interactive = true,
  label = "Tube grid",
  className,
  style,
  onPointerMove,
  onPointerLeave,
  onPointerDown,
  ...props
}: TubeGridProps) {
  const rootRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const [fallback, setFallback] = React.useState(false)
  const pointer = React.useRef({ x: 0, y: 0, on: 0, click: -1 })
  const kick = React.useRef<() => void>(() => {})
  const nr = Math.max(1, Math.min(15, Math.round(rows)))
  const nc = Math.max(1, Math.min(15, Math.round(cols)))

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || fallback) return
    const gl = canvas.getContext("webgl", { alpha: false, antialias: false, premultipliedAlpha: false })
    if (!gl) {
      setFallback(true)
      return
    }
    const vs = compile(gl, gl.VERTEX_SHADER, VERT)
    const vsScreen = compile(gl, gl.VERTEX_SHADER, SCREEN_VERT)
    const made: WebGLShader[] = [vs, vsScreen]
    const link = (src: string, v = vs) => {
      const fs = compile(gl, gl.FRAGMENT_SHADER, src)
      made.push(fs)
      const p = gl.createProgram()!
      gl.attachShader(p, v)
      gl.attachShader(p, fs)
      gl.bindAttribLocation(p, 0, "aPos")
      gl.linkProgram(p)
      return gl.getProgramParameter(p, gl.LINK_STATUS) ? p : null
    }
    const pBody = link(BODY_FRAG)
    const pDisc = link(DISC_FRAG)
    const pGlow = link(GLOW_FRAG)
    const pRamp = link(RAMP_FRAG, vsScreen)
    if (!pBody || !pDisc || !pGlow || !pRamp) {
      setFallback(true)
      return
    }
    // The light buffer: half float where the device can render to it, else dithered 8 bit.
    const hf = gl.getExtension("OES_texture_half_float")
    gl.getExtension("EXT_color_buffer_half_float")
    const tex = gl.createTexture()
    const fbo = gl.createFramebuffer()
    let texType: number = hf ? hf.HALF_FLOAT_OES : gl.UNSIGNED_BYTE
    const allocate = (w: number, h: number) => {
      gl.bindTexture(gl.TEXTURE_2D, tex)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, texType, null)
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo)
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0)
      if (texType !== gl.UNSIGNED_BYTE && gl.checkFramebufferStatus(gl.FRAMEBUFFER) !== gl.FRAMEBUFFER_COMPLETE) {
        texType = gl.UNSIGNED_BYTE
        allocate(w, h)
      }
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
    }
    const buf = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buf)
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]), gl.STATIC_DRAW)
    gl.enableVertexAttribArray(0)
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)

    const locs = (p: WebGLProgram, names: string[]) => {
      const o: Record<string, WebGLUniformLocation | null> = {}
      for (const n of names) o[n] = gl.getUniformLocation(p, n)
      return o
    }
    const rampNames = ["uBg", "uC1", "uC2", "uC3", "uC4", "uC5", "uWarm"]
    const U = {
      body: locs(pBody, ["uBox", "uView", "uP", "uF", "uGeo", "uTail", "uB", "uB2", "uE", "uPulse", "uDither"]),
      disc: locs(pDisc, ["uBox", "uView", "uP", "uRot", "uQ", "uHq", "uFx", "uDither"]),
      glow: locs(pGlow, ["uBox", "uView", "uP", "uG"]),
      ramp: locs(pRamp, ["uLight", ...rampNames]),
    }
    const pal = palette(color, highlight, shade, tint, background)
    gl.useProgram(pRamp)
    pal.stops.forEach((c, i) => gl.uniform3f(U.ramp[rampNames[i]], c[0], c[1], c[2]))
    gl.uniform3f(U.ramp.uWarm, pal.warm[0], pal.warm[1], pal.warm[2])
    gl.uniform1i(U.ramp.uLight, 0)
    // Disc coefficients are constant: pack them once.
    const discQ = DISC.map((d) => {
      const a = new Float32Array(20)
      a.set(d.slice(0, 18))
      return a
    })
    const discH = DISC.map((d) => new Float32Array(d.slice(18, 24)))

    const tubes = layout(nr, nc)
    const order = tubes.map((_, i) => i)
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    const moving = !reduce && speed > 0
    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    let cssW = 0, cssH = 0, cw = 0, ch = 0, k = 1
    const spanX = (nc - 1) * PITCH + 2 * RADIUS + 2 * MARGIN
    const spanY = (nr - 1) * PITCH + 2 * RADIUS + 2 * MARGIN
    const resize = () => {
      const r = canvas.getBoundingClientRect()
      cssW = r.width
      cssH = r.height
      cw = Math.max(1, Math.round(r.width * dpr))
      ch = Math.max(1, Math.round(r.height * dpr))
      if (canvas.width !== cw || canvas.height !== ch) {
        canvas.width = cw
        canvas.height = ch
      }
      k = Math.max(spanX / Math.max(cssW, 1), spanY / Math.max(cssH, 1))
      allocate(cw, ch)
      gl.viewport(0, 0, cw, ch)
      kick.current()
    }
    const ro = new ResizeObserver(resize)
    ro.observe(canvas)
    resize()

    const sx: Spring = { x: 0, v: 0 }
    const sy: Spring = { x: 0, v: 0 }
    let raf = 0
    let visible = !document.hidden
    let onScreen = true
    let last = -1
    let clock = 0
    const start = performance.now()
    const io = new IntersectionObserver(([e]) => {
      onScreen = e.isIntersecting
      kick.current()
    })
    io.observe(canvas)
    const vis = () => {
      visible = !document.hidden
      last = -1
      kick.current()
    }
    document.addEventListener("visibilitychange", vis)

    const [, , s0, blur, gam, blur1, tailA, tailW] = GLOBAL

    function frame(now: number) {
      raf = 0
      if (cssW < 1 || cssH < 1 || !gl) return
      const dt = last < 0 ? 0 : Math.min(Math.max(now - last, 0) / 1000, 1 / 20)
      last = now
      // The orbit follows wall time, so a dropped frame never slows it down.
      if (moving) clock = ((now - start) / 1000) * speed
      const ph = (TAU * (((clock % LOOP) + LOOP) % LOOP)) / LOOP
      const p = pointer.current
      const live = interactive && !reduce
      const on = live ? p.on : 0
      step(sx, on ? (p.x - cssW / 2) * k * STEER : 0, dt, 4)
      step(sy, on ? (p.y - cssH / 2) * k * STEER : 0, dt, 4)
      const S = scene(ph, sx.x, sy.x)
      const tau = live && p.click >= 0 ? (now - p.click) / 1000 : -1
      const breath = S.breath * Math.max(0, glow)

      const Wr = cssW * k, Hr = cssH * k
      const view = [0, 0, 2 / Wr, 2 / Hr]
      const pxRef = k / dpr
      const dither = texType === gl.UNSIGNED_BYTE ? 1 / 255 : 0
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo)
      gl.enable(gl.BLEND)
      gl.clearColor(0, 0, 0, 0)
      gl.clear(gl.COLOR_BUFFER_BIT)

      // Bodies, farthest from the vanishing point first: a tube nearer the axis is nearer the
      // camera wherever two bodies cross.
      order.sort((a, b) => Math.hypot(tubes[b].x - S.vx, tubes[b].y - S.vy) - Math.hypot(tubes[a].x - S.vx, tubes[a].y - S.vy))
      gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA)
      gl.useProgram(pBody)
      const ub = U.body
      gl.uniform4f(ub.uView, view[0], view[1], view[2], view[3])
      gl.uniform1f(ub.uDither, dither)
      // The discs sit still while the far ends swing, with a touch of parallax.
      const parX = -S.dvx * 0.05, parY = -S.dvy * 0.05
      for (const idx of order) {
        const t = tubes[idx]
        const b = BODY[t.prof]
        const px = t.x + parX, py = t.y + parY
        const sk = 1 - (1 - s0) * b[6]
        const fx = S.vx + (px - S.vx) * sk, fy = S.vy + (py - S.vy) * sk
        const m = RADIUS * (1 + tailW * 3.4) + blur * 2 + blur1
        gl.uniform4f(ub.uBox, Math.min(px, fx) - m, Math.min(py, fy) - m, Math.max(px, fx) + m, Math.max(py, fy) + m)
        gl.uniform2f(ub.uP, px, py)
        gl.uniform2f(ub.uF, fx, fy)
        gl.uniform4f(ub.uGeo, RADIUS, sk, blur, blur1)
        gl.uniform2f(ub.uTail, tailA, Math.max(tailW, 0.02))
        const sway = 0.12 * (Math.sin(ph + t.phase) - Math.sin(t.phase))
        gl.uniform4f(ub.uB, b[0] * (1 + 0.05 * breath), b[1] * (1 + 0.12 * breath), b[2] + sway, b[3])
        gl.uniform3f(ub.uB2, b[8] * (1 + 0.12 * breath), b[9] - sway, b[10])
        gl.uniform4f(ub.uE, gam * b[7], b[4], b[5], 0)
        const pu = pulseAt(t, tau)
        gl.uniform2f(ub.uPulse, pu.pos, pu.amp)
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
      }

      // Breathing glow, added around the discs.
      if (breath > 0.002) {
        gl.blendFunc(gl.ONE, gl.ONE)
        gl.useProgram(pGlow)
        gl.uniform4f(U.glow.uView, view[0], view[1], view[2], view[3])
        for (const t of tubes) {
          const px = t.x + parX, py = t.y + parY, m = RADIUS * 2
          gl.uniform4f(U.glow.uBox, px - m, py - m, px + m, py + m)
          gl.uniform2f(U.glow.uP, px, py)
          gl.uniform3f(U.glow.uG, RADIUS, 0.07 * breath, 0)
          gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
        }
        gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA)
      }

      gl.useProgram(pDisc)
      const ud = U.disc
      gl.uniform4f(ud.uView, view[0], view[1], view[2], view[3])
      gl.uniform1f(ud.uDither, dither)
      for (const t of tubes) {
        const px = t.x + parX, py = t.y + parY, m = RADIUS + 2
        const a = lightTurn(t, S.vx, S.vy, ph)
        gl.uniform4f(ud.uBox, px - m, py - m, px + m, py + m)
        gl.uniform2f(ud.uP, px, py)
        gl.uniform4f(ud.uRot, Math.cos(a), Math.sin(a), RADIUS, 0)
        gl.uniform4fv(ud.uQ, discQ[t.prof])
        gl.uniform3fv(ud.uHq, discH[t.prof])
        const fl = pulseAt(t, tau).flash
        gl.uniform3f(ud.uFx, Math.max(1.4, pxRef * 1.1), 1 - 0.3 * fl, 0.03 * breath + 0.55 * fl)
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
      }

      // Light through the colour ramp onto the canvas.
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      gl.disable(gl.BLEND)
      gl.useProgram(pRamp)
      gl.activeTexture(gl.TEXTURE0)
      gl.bindTexture(gl.TEXTURE_2D, tex)
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)

      const pulsing = tau >= 0 && tau < 3
      const settled = Math.abs(sx.v) + Math.abs(sy.v) + Math.abs(sx.x - (on ? (p.x - cssW / 2) * k * STEER : 0)) < 1e-2
      if (visible && onScreen && (moving || pulsing || !settled)) raf = requestAnimationFrame(frame)
    }
    kick.current = () => {
      if (visible && onScreen && !raf) raf = requestAnimationFrame(frame)
    }
    raf = requestAnimationFrame(frame)

    const lost = (e: Event) => {
      e.preventDefault()
      setFallback(true)
    }
    canvas.addEventListener("webglcontextlost", lost)
    return () => {
      cancelAnimationFrame(raf)
      io.disconnect()
      ro.disconnect()
      document.removeEventListener("visibilitychange", vis)
      kick.current = () => {}
      canvas.removeEventListener("webglcontextlost", lost)
      for (const p of [pBody, pDisc, pGlow, pRamp]) gl.deleteProgram(p)
      gl.deleteTexture(tex)
      gl.deleteFramebuffer(fbo)
      for (const s of made) gl.deleteShader(s)
      gl.deleteBuffer(buf)
    }
  }, [nr, nc, color, highlight, shade, tint, background, speed, glow, interactive, fallback])

  const track = (e: React.PointerEvent<HTMLDivElement>) => {
    const r = rootRef.current?.getBoundingClientRect()
    if (!r) return
    pointer.current.x = e.clientX - r.left
    pointer.current.y = e.clientY - r.top
    pointer.current.on = 1
    kick.current()
  }

  return (
    <div
      ref={rootRef}
      role={children ? undefined : "img"}
      aria-label={children ? undefined : label}
      className={className}
      style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden", background, ...style }}
      onPointerMove={(e) => {
        if (interactive) track(e)
        onPointerMove?.(e)
      }}
      onPointerDown={(e) => {
        if (interactive) {
          track(e)
          pointer.current.click = performance.now()
          kick.current()
        }
        onPointerDown?.(e)
      }}
      onPointerLeave={(e) => {
        pointer.current.on = 0
        kick.current()
        onPointerLeave?.(e)
      }}
      {...props}
    >
      {fallback ? (
        <Fallback rows={nr} cols={nc} color={color} highlight={highlight} shade={shade} tint={tint} background={background} />
      ) : (
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block", pointerEvents: "none" }}
        />
      )}
      {children ? (
        <div style={{ position: "relative", height: "100%", display: "flex", alignItems: "center", justifyContent: "center" }}>
          {children}
        </div>
      ) : null}
    </div>
  )
}

// No WebGL: the same model drawn once on the CPU into a 2D canvas (the resting frame, still).
function Fallback({ rows, cols, color, highlight, shade, tint, background }: { rows: number; cols: number; color: string; highlight: string; shade: string; tint: string; background: string }) {
  const ref = React.useRef<HTMLCanvasElement>(null)
  React.useEffect(() => {
    const canvas = ref.current
    if (!canvas) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return
    const pal = palette(color, highlight, shade, tint, background)
    const st = pal.stops
    const ramp = (q: number, h: number, out: number[]) => {
      const s = Math.min(Math.max(q, 0), 1) * 5
      const i = Math.min(4, Math.floor(s))
      const f = s - i
      const w = 0.25 * Math.min(Math.max(s - 2, 0), 1) + 0.75 * Math.min(Math.max(s - 3, 0), 1) - 0.5 * Math.min(Math.max(s - 4, 0), 1)
      const hh = Math.min(Math.max(h, 0), 1) * w
      for (let c = 0; c < 3; c++) out[c] = st[i][c] + (st[i + 1][c] - st[i][c]) * f + hh * pal.warm[c]
    }
    const tubes = layout(rows, cols)
    const [vx, vy, s0, blur, gam, blur1, tailA, tailW] = GLOBAL
    const draw = () => {
      const r = canvas.getBoundingClientRect()
      const scale = Math.min(1, 420 / Math.max(r.width, r.height, 1))
      const W = Math.max(1, Math.round(r.width * scale)), H = Math.max(1, Math.round(r.height * scale))
      canvas.width = W
      canvas.height = H
      const spanX = (cols - 1) * PITCH + 2 * RADIUS + 2 * MARGIN
      const spanY = (rows - 1) * PITCH + 2 * RADIUS + 2 * MARGIN
      const k = Math.max(spanX / W, spanY / H)
      const img = ctx.createImageData(W, H)
      // light (q) and lavender (h) per pixel, blended layer over layer, then through the ramp
      const buf = new Float32Array(W * H * 2)
      const col = [0, 0, 0]
      const order = tubes.map((_, i) => i).sort((a, b) => Math.hypot(tubes[b].x - vx, tubes[b].y - vy) - Math.hypot(tubes[a].x - vx, tubes[a].y - vy))
      const box = (x0: number, y0: number, x1: number, y1: number, fn: (x: number, y: number, n: number) => void) => {
        const a0 = Math.max(0, Math.floor(x0 / k + W / 2)), a1 = Math.min(W - 1, Math.ceil(x1 / k + W / 2))
        const b0 = Math.max(0, Math.floor(y0 / k + H / 2)), b1 = Math.min(H - 1, Math.ceil(y1 / k + H / 2))
        for (let yy = b0; yy <= b1; yy++) for (let xx = a0; xx <= a1; xx++) fn((xx + 0.5 - W / 2) * k, (yy + 0.5 - H / 2) * k, yy * W + xx)
      }
      for (const idx of order) {
        const t = tubes[idx]
        const b = BODY[t.prof]
        const sk = 1 - (1 - s0) * b[6]
        const fx = vx + (t.x - vx) * sk, fy = vy + (t.y - vy) * sk
        const Dx = fx - t.x, Dy = fy - t.y, L2 = Dx * Dx + Dy * Dy + 1e-4, L = Math.sqrt(L2)
        const m = RADIUS * (1 + tailW * 3.4) + blur * 2 + blur1
        box(Math.min(t.x, fx) - m, Math.min(t.y, fy) - m, Math.max(t.x, fx) + m, Math.max(t.y, fy) + m, (x, y, n) => {
          const dx = x - t.x, dy = y - t.y
          const tt = (dx * Dx + dy * Dy) / L2
          const tc = Math.min(Math.max(tt, 0), 1)
          const rr = RADIUS * (1 + (sk - 1) * tc)
          const ax = dx - tc * Dx, ay = dy - tc * Dy
          const dist = Math.hypot(ax, ay)
          const w = (Dx * ay - Dy * ax) / L / rr
          const bw = (blur + blur1 * tc) / rr
          let kk = Math.min(Math.max((1 + bw - dist / rr) / (2 * bw), 0), 1)
          kk = kk * kk * (3 - 2 * kk)
          kk = Math.max(kk, tailA * Math.exp(-Math.max(dist / rr - 1, 0) / Math.max(tailW, 0.02)))
          const u = Math.min(Math.max(1 - tt, 0), 1)
          let nc = Math.min(Math.max((tt * L + 0.15 * RADIUS) / (0.4 * RADIUS), 0), 1)
          nc = nc * nc * (3 - 2 * nc)
          const alpha = kk * b[5] * Math.min(u / 0.25, 1) * nc
          if (alpha <= 0) return
          const q = (b[0] + b[1] * Math.exp(-Math.pow((w - b[2]) / Math.max(b[3], 0.05), 2)) + b[8] * Math.exp(-Math.pow((w - b[9]) / Math.max(b[10], 0.05), 2))) * Math.pow(u, gam * b[7])
          buf[n * 2] += (q - buf[n * 2]) * alpha
          buf[n * 2 + 1] += (b[4] - buf[n * 2 + 1]) * alpha
        })
      }
      for (const t of tubes) {
        const d = DISC[t.prof]
        const m = RADIUS + 2
        box(t.x - m, t.y - m, t.x + m, t.y + m, (px, py, n) => {
          const x = (px - t.x) / RADIUS, y = (py - t.y) / RADIUS
          const r = Math.hypot(x, y)
          const alpha = Math.min(Math.max(((1 - r) * RADIUS) / Math.max(1.4, k) + 0.5, 0), 1)
          if (alpha <= 0) return
          const x2 = x * x, y2 = y * y, xy = x * y, r8 = Math.pow(x2 + y2, 4)
          const B = [1, x, y, x2, xy, y2, x2 * x, x2 * y, x * y2, y2 * y, x2 * x2, x2 * xy, x2 * y2, xy * y2, y2 * y2, r8, r8 * x, r8 * y]
          let q = 0
          for (let i = 0; i < 18; i++) q += d[i] * B[i]
          let h = 0
          for (let i = 0; i < 6; i++) h += d[18 + i] * B[i]
          buf[n * 2] += (q - buf[n * 2]) * alpha
          buf[n * 2 + 1] += (h - buf[n * 2 + 1]) * alpha
        })
      }
      for (let n = 0; n < W * H; n++) {
        ramp(buf[n * 2], buf[n * 2 + 1], col)
        img.data[n * 4] = col[0] * 255
        img.data[n * 4 + 1] = col[1] * 255
        img.data[n * 4 + 2] = col[2] * 255
        img.data[n * 4 + 3] = 255
      }
      ctx.putImageData(img, 0, 0)
    }
    const ro = new ResizeObserver(draw)
    ro.observe(canvas)
    return () => ro.disconnect()
  }, [rows, cols, color, highlight, shade, tint, background])
  return <canvas ref={ref} aria-hidden="true" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }} />
}

